import attr
from typing import Union
from taf.config.testline.ue import CUS as CusTaf  # type: ignore
from taf.ul.ue.sim.env_setup.utils.enums import DevicesNames
from ute_testline_configuration.ute_config import CUS as CusUte  # type: ignore
from taf.ul.ue.sim.env_setup.devices.rtg_cus_generic import RtgCusGenericInterface


@attr.s(cmp=False, hash=True)
class CUS(RtgCusGenericInterface):
    idx = attr.ib(type=int)
    remote_host = attr.ib(type=str, repr=False)
    output_directory_path = attr.ib(type=str)
    configuration = attr.ib(type=Union[CusUte, CusTaf], hash=False)
    config_type = attr.ib(type="str")
    name = attr.ib(type=DevicesNames, default=DevicesNames.CUS, init=False)

    def _get_taf_pdu_config(self):
        return self.configuration.l1.common_units[0].pdu_port
